"""Prototype implicitly restarted Arnoldi in Numba for largest-modulus eigenpairs."""
import time
import numpy as np
from numba import njit
from reference import Task

@njit(cache=False)
def csr_matvec(indptr, indices, data, x, y):
    n = x.shape[0]
    for i in range(n):
        s = 0.0
        for j in range(indptr[i], indptr[i + 1]):
            s += data[j] * x[indices[j]]
        y[i] = s

@njit(cache=False)
def dot(a, b):
    s = 0.0
    for i in range(a.shape[0]):
        s += a[i] * b[i]
    return s

@njit(cache=False)
def nrm2(a):
    return np.sqrt(dot(a, a))

@njit(cache=False)
def axpy(a, x, y):
    # y += a*x
    for i in range(y.shape[0]):
        y[i] += a * x[i]

@njit(cache=False)
def scale(a, x):
    for i in range(x.shape[0]):
        x[i] *= a

@njit(cache=False)
def copy(dst, src):
    for i in range(dst.shape[0]):
        dst[i] = src[i]

@njit(cache=False)
def orthogonalize(v, V, k, h):
    """Modified Gram-Schmidt of v against V[:, :k]. h length k filled. returns new norm of v."""
    n = v.shape[0]
    for i in range(k):
        s = 0.0
        Vi = V[:, i]
        for j in range(n):
            s += Vi[j] * v[j]
        h[i] = s
        for j in range(n):
            v[j] -= s * Vi[j]
    # reortho once
    for i in range(k):
        s = 0.0
        Vi = V[:, i]
        for j in range(n):
            s += Vi[j] * v[j]
        h[i] += s
        for j in range(n):
            v[j] -= s * Vi[j]
    return nrm2(v)

@njit(cache=False)
def arnoldi(indptr, indices, data, v0, k, ncv, maxiter, tol):
    """
    Implicitly restarted Arnoldi for k largest-modulus eigenvalues.
    Returns eigenvalues (complex as pairs real/imag) and eigenvectors (n, k) complex stored as real,imag interleaved? 
    We'll return real Ritz values wr, wi and real basis V (n, ncv) and Hessenberg H (ncv, ncv) of final iteration,
    then finish in python. For correctness prototype, do full QR algorithm on small H in python after enough iterations
    of explicitly restarted Arnoldi (simpler, slower convergence).
    """
    n = v0.shape[0]
    V = np.zeros((n, ncv + 1))
    H = np.zeros((ncv + 1, ncv))
    w = np.empty(n)
    # start
    nv = nrm2(v0)
    for i in range(n):
        V[i, 0] = v0[i] / nv

    hcol = np.empty(ncv + 1)
    for j in range(ncv):
        csr_matvec(indptr, indices, data, V[:, j], w)
        beta = orthogonalize(w, V, j + 1, hcol)
        for i in range(j + 1):
            H[i, j] = hcol[i]
        H[j + 1, j] = beta
        if beta < 1e-14:
            break
        invb = 1.0 / beta
        for i in range(n):
            V[i, j + 1] = w[i] * invb
    return V, H

def main():
    task = Task()
    p = task.generate_problem(n=300, random_seed=1)
    A = p["matrix"].tocsr()
    n = A.shape[0]
    v0 = np.ones(n)
    # compile
    V, H = arnoldi(A.indptr, A.indices, A.data, v0, 5, 20, 10, 0.0)
    t0 = time.perf_counter()
    for _ in range(5):
        V, H = arnoldi(A.indptr, A.indices, A.data, v0, 5, 30, 10, 0.0)
    print("one arnoldi ncv=30", (time.perf_counter()-t0)/5)
    # Ritz
    # H is (ncv+1, ncv), use H[:ncv,:ncv]
    ncv = 30
    He = H[:ncv, :ncv].copy()
    evals, evecs = np.linalg.eig(He)
    order = np.argsort(-np.abs(evals))
    print("ritz abs", np.abs(evals[order][:8]))
    # compare to reference
    ref = task.solve(p)
    # build vectors
    vecs = V[:, :ncv] @ evecs[:, order[:5]]
    sims = []
    for i in range(5):
        v = vecs[:, i]
        r = ref[i]
        sims.append(abs(np.vdot(v, r)) / (np.linalg.norm(v)*np.linalg.norm(r)))
    print("sims one-shot ncv=30", sims)

    # larger ncv
    t0 = time.perf_counter()
    V, H = arnoldi(A.indptr, A.indices, A.data, v0, 5, 80, 10, 0.0)
    print("arnoldi ncv=80", time.perf_counter()-t0)
    He = H[:80, :80]
    evals, evecs = np.linalg.eig(He)
    order = np.argsort(-np.abs(evals))
    print("ritz abs", np.abs(evals[order][:8]))
    vecs = V[:, :80] @ evecs[:, order[:5]]
    sims = []
    for i in range(5):
        v = vecs[:, i]
        r = ref[i]
        sims.append(abs(np.vdot(v, r)) / (np.linalg.norm(v)*np.linalg.norm(r)))
    print("sims ncv=80", sims)

if __name__ == "__main__":
    main()
